import type { CommandOutput } from "@code-health/cli-kit/run-cli";

/**
 * Folders that often hold code that is not the product (examples, samples, test inputs, benchmarks), by naming
 * conventions that vary between repositories, so they are not made tests or generated by default. A command that ranks
 * or counts production code names the ones it met, with their share of its production files, and the files stay in
 * its results. Each pattern is matched against the folders of a path, at any depth, case-insensitively.
 */
const CONVENTIONS: readonly RegExp[] = [
  /(?:^|\/)(?:examples|samples|sample|playground|benches|integration)\//i,
  /(?:^|\/)src\/it\//i,
  /(?:^|\/)src\/[^/]+\/resources\//i,
];

export interface NonProductionFolder {
  /** The folder, repo-relative, ending at the convention's last segment (`playground`, `crates/x/benches`, `src/main/resources`). */
  folder: string;
  /** The production files below it among those the command counted. */
  files: number;
  /** `files` as a share of the production files the command counted, from 0 to 1, to four places. */
  share: number;
}

export interface NonProductionFolders {
  /** The production files the command counted. */
  productionFiles: number;
  /** The folders met, most files first, then by path. A folder inside another is counted in the outer one only. */
  folders: NonProductionFolder[];
}

/** The folder of `path` that a convention names: the one whose match ends first in the path, or undefined. */
export function nonProductionFolderOf(path: string): string | undefined {
  const directory = path.slice(0, path.lastIndexOf("/") + 1);
  let end: number | undefined;
  for (const convention of CONVENTIONS) {
    const match = convention.exec(directory);
    if (match === null) continue;
    const matchEnd = match.index + match[0].length - 1;
    if (end === undefined || matchEnd < end) end = matchEnd;
  }
  return end === undefined ? undefined : directory.slice(0, end);
}

/** The folders that the conventions name among `productionPaths`, with their counts. Undefined when there are none. */
export function nonProductionFolders(productionPaths: Iterable<string>): NonProductionFolders | undefined {
  const counts = new Map<string, number>();
  let total = 0;
  for (const path of productionPaths) {
    total++;
    const folder = nonProductionFolderOf(path);
    if (folder !== undefined) counts.set(folder, (counts.get(folder) ?? 0) + 1);
  }
  if (counts.size === 0) return undefined;
  const folders = [...counts]
    .map(([folder, files]) => ({ folder, files, share: Math.round((files / total) * 10000) / 10000 }))
    .sort((a, b) => b.files - a.files || (a.folder < b.folder ? -1 : a.folder > b.folder ? 1 : 0));
  return { productionFiles: total, folders };
}

/**
 * Adds `possibleNonProductionFolders` and its notice to a command's output when `productionPaths` has files in such
 * folders. The results are returned as they are.
 */
export function withNonProductionFolders(output: CommandOutput, productionPaths: Iterable<string>): CommandOutput {
  const found = nonProductionFolders(productionPaths);
  if (found === undefined) return output;
  return {
    ...output,
    extra: { ...output.extra, possibleNonProductionFolders: found },
    notices: [...(output.notices ?? []), nonProductionFoldersNotice(found)],
  };
}

/** Folders the notice names before it counts the rest. */
const NAMED_IN_NOTICE = 5;

/** The notice line for a table run. */
export function nonProductionFoldersNotice(found: NonProductionFolders): string {
  const share = (value: number) => `${(value * 100).toFixed(1)}%`;
  const named = found.folders.slice(0, NAMED_IN_NOTICE).map((entry) => `${entry.folder}/ ${entry.files} (${share(entry.share)})`);
  const rest = found.folders.slice(NAMED_IN_NOTICE);
  const restFiles = rest.reduce((sum, entry) => sum + entry.files, 0);
  const more = rest.length === 0 ? "" : ` and ${rest.length} more ${rest.length === 1 ? "folder" : "folders"} with ${restFiles} ${restFiles === 1 ? "file" : "files"}`;
  const totalFiles = found.folders.reduce((sum, entry) => sum + entry.files, 0);
  return (
    `${totalFiles} of ${found.productionFiles} production files (${share(totalFiles / found.productionFiles)}) are in folders that often hold examples, samples, test inputs or benchmarks: ` +
    `${named.join(", ")}${more}; they are counted as production code, and listing a folder in exclude (such as ${found.folders[0]!.folder}/**) leaves it out, and possibleNonProductionFolders in the JSON lists every folder`
  );
}
